questionvariables.text:
/* Fixed meaning, context randomised: 1 = Meru coffee farmers to cooperative societies,
   2 = Kericho tea villages to one collection centre (merged from Relations Q6).
   Both are many-to-one, and both are functions. */
ctx: rand([1, 2]);
nf: rand([20, 30, 40, 50]);
nc: rand([2, 3, 4]);
correct: manytoone;
ta1: [[onetoone, is(correct=onetoone), "one-to-one"],
     [onetomany, is(correct=onetomany), "one-to-many"],
     [manytoone, is(correct=manytoone), "many-to-one"],
     [manytomany, is(correct=manytomany), "many-to-many"]];
tac1: first(mcq_correct(ta1));
ta2: [[fnA, false, "It is not a function, because several inputs are linked to the same output."],
      [fnB, true, "It is a function, because every input is linked to exactly one output."],
      [fnC, false, "It is not a function, because a function must be one-to-one."]];
tac2: first(mcq_correct(ta2));
